import { Suspense } from 'react';
import { notFound } from 'next/navigation';
import type { Metadata } from 'next';

interface PageProps {
  params: Promise<{ slug: string }>;
}

async function fetchPost(slug: string) {
  // Simulated database or CMS query
  if (slug === 'not-found') return null;
  return {
    slug,
    title: `Architecting Scalable Next.js Applications (${slug})`,
    summary: 'A deep dive into Next.js App Router performance and streaming.',
    author: 'SopuCoder Team',
    publishedAt: '2026-11-12',
    content: 'Full article body content goes here...'
  };
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const post = await fetchPost(slug);
  if (!post) return { title: 'Post Not Found' };

  return {
    title: `${post.title} | SopuCoder Blog`,
    description: post.summary,
    openGraph: {
      title: post.title,
      description: post.summary,
      type: 'article',
      publishedTime: post.publishedAt,
      authors: [post.author],
    },
  };
}

async function PostContent({ slug }: { slug: string }) {
  const post = await fetchPost(slug);
  if (!post) notFound();

  return (
    <article className="prose mx-auto max-w-3xl py-8">
      <h1 className="text-3xl font-bold tracking-tight">{post.title}</h1>
      <p className="text-sm text-gray-500">By {post.author} on {post.publishedAt}</p>
      <div className="mt-6 leading-relaxed">{post.content}</div>
    </article>
  );
}

export default async function BlogPostPage({ params }: PageProps) {
  const { slug } = await params;
  return (
    <main className="container mx-auto px-4">
      <Suspense fallback={<div className="animate-pulse py-12 text-center">Loading post...</div>}>
        <PostContent slug={slug} />
      </Suspense>
    </main>
  );
}
